    // MARK: - Equipped App Theme

    private var equippedAppTheme: CosmeticDefinition? {

        guard let themeID =
            gamificationViewModel.equippedCosmeticID(for: "theme") else {

            return nil
        }

        return gamificationViewModel.cosmeticCatalog.first {
            $0.id == themeID && $0.cosmetic_type == "theme"
        }
    }


    // MARK: - Equipped Theme Color

    private var equippedThemeTint: Color? {

        guard let theme = equippedAppTheme else {
            return nil
        }

        switch theme.collection {

        case "astral":
            return .purple

        case "nature":
            return .green

        case "cyber":
            return .cyan

        default:
            return nil
        }
    }

    
