                // -----------------------------
                // Step Goal
                // -----------------------------

                if goal.goal_type == "increase_steps" &&
                    goal.unit == "steps" {

                    HStack {

                        if let steps = viewModel.steps {

                            Text("\(steps.formatted()) steps")

                        } else {

                            Text("-- steps")
                        }

                        Spacer()

                        Image(systemName: "arrow.right")

                        Spacer()

                        Text(
                            "\(goal.target_value.formatted()) steps"
                        )
                    }
                    .foregroundColor(.secondary)

                    ProgressView(
